import{S as d,o as s,c as r,a9 as a,B as c}from"./chunks/framework.DxG24V0C.js";const p=JSON.parse('{"title":"Capability 缝体系：为什么换一个实现能牵一发动全身","description":"","frontmatter":{"title":"Capability 缝体系：为什么换一个实现能牵一发动全身"},"headers":[],"relativePath":"deepseek/06-capability-seams.md","filePath":"deepseek/06-capability-seams.md","lastUpdated":1787409644000}'),n={name:"deepseek/06-capability-seams.md"},h=Object.assign(n,{setup(i){const e=[{question:'要完整地做出一个"能力"，最少要设计哪三种可独立演化的角色？',options:["接口、一个实现、一个开关","接口、一个实现、一段日志","实现、消费方、周边工具包","服务定义、服务实现、服务消费者"],correct:3,explanation:"capability 缝 = Service Definition + Provider + Consumer（后者一般是 model-facing tool）。只做其中一个角色不构成 seam。"},{question:"为什么 Consumer 只依赖服务接口（Service Definition）而不 import 具体 Provider？",options:["因为接口往往更短更好读","因为 import 一个包就会死循环","因为否则换 Provider 时 Consumer 也得改","因为 Provider 不对外暴露方法"],correct:2,explanation:'Consumer 只依赖服务接口、不 import 实现，所以换 Provider 时 Consumer 与整个产品都不动。这是"可换缝"成立的关键。'},{question:'"Provider 互换会整套移动" 最根本的原因是什么？',options:["多个缝往往共享同一个执行世界","新 Provider 通常代码量更少","因为产品只允许单进程","因为 Provider 决定 CPU 频率"],correct:0,explanation:'fs 与 subprocess 共享"执行世界"，bash/PTY/LSP 都经 ctx.subprocess 这条缝去 spawn，换一组 provider 时这些能力成套迁移、无分叉。'},{question:"seam 中 Service Definition 的职责，最匹配的是哪一项？",options:["定义接口、词汇、事件，并独立于实现","把接口与实现写进同一个包","只负责本地的具体落盘实现","生成给模型看的精确参数 schema"],correct:0,explanation:"Definition 定义接口与词汇并独立于后端；Provider 是具体实现；Consumer 才提供模型 schema——三者分工明确。"},{question:"`sandboxMode` 这个能力事实的作用是什么？",options:["它是仅供内部参考的调试标记","Provider 填一个事实，Consumer 据它决定是否暴露沙箱字段","它强制模型每步都必须用沙箱","它让所有工具天生都带沙箱"],correct:1,explanation:'Provider 在 `ctx.shell` 上填 `sandboxMode`；Consumer 读它来决定是否给工具 schema 加"要求沙箱"字段，而无需知道 bwrap/Landlock 等后端细节。'}];return(l,o)=>{const t=d("Quiz");return s(),r("div",null,[o[0]||(o[0]=a("",62)),c(t,{questions:e})])}}});export{p as __pageData,h as default};
